/// <summary>
/// TelemetryShipConfirm class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetryLedgerJournalCheckPostLogging extends METTelemetryBase
{
    public Notes errmsg;

}

Method.Source:
/// <summary>
/// constructor
/// </summary>
/// <param name = "_errmsg">_errmsg</param>
protected void new(Notes _errmsg)
{
    super();
    this.eventId = METApplicationInsightsEventIds::DMFLedgerJournalPost;
    errmsg = _errmsg;
}

/// <summary>
/// METTelemetryLedgerJournalCheckPostLogging
/// </summary>
/// <param name = "_errmsg">_errmsg</param>
/// <returns>METTelemetryLedgerJournalCheckPostLogging</returns>
public static METTelemetryLedgerJournalCheckPostLogging construct(Notes _errmsg)
{
    return new METTelemetryLedgerJournalCheckPostLogging(_errmsg);
}

/// <summary>
/// shouldLogEvent
/// </summary>
/// <returns>boolean</returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// populateProperties
/// </summary>
protected void populateProperties()
{
    this.setElapsedMilliseconds();
    this.addBaseProperty(METApplicationInsightsEventProperties::LegalEntity, curExt());
    this.addBaseProperty(METApplicationInsightsEventProperties::ExceptionMessage, errmsg);
    this.addBaseProperty(METApplicationInsightsEventProperties::CallStack, METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
}
